const assert=require('node:assert/strict');
const fs=require('node:fs');
module.exports=async function checkAmazonia(page){
 const base='http://127.0.0.1:8765/';
 const entry=JSON.parse(fs.readFileSync('entries/amazonia.json','utf8'));
 assert.equal(entry.shots.length,38);assert.equal(entry.prompts.length,9);
 assert.equal(entry.cases.filter(c=>c.kind!=='palette').length,10);
 const palette=entry.cases.find(c=>c.kind==='palette');assert.equal(palette.palette.groups.length,5);
 for(const p of [entry.preview,entry.poster,entry.report])assert.ok(fs.existsSync(p),p);
 for(const s of entry.shots)for(const f of Object.values(s.frames))assert.ok(fs.existsSync('reports/amazonia/'+f.src));
 await page.setViewportSize({width:1440,height:1000});await page.goto(base);await page.evaluate(()=>window.FILM_LIBRARY_READY);
 await page.locator('.category-nav [data-direction="审美短片"]').click();
 assert.equal(await page.locator('#video-grid [data-open="amazonia"]').count(),1);
 await page.locator('#search').fill('亚马逊');assert.equal(await page.locator('#video-grid .video-card').count(),1);
 await page.locator('#video-grid [data-open="amazonia"]').click();
 assert.equal(await page.locator('#detail-categories').innerText(),'审美短片');
 await page.waitForFunction(()=>document.querySelector('#detail-video').readyState>=1);
 assert.ok(Math.abs(await page.locator('#detail-video').evaluate(v=>v.duration)-entry.duration)<.1);
 await page.locator('#tab-cases').click();
 assert.equal(await page.locator('#detail-panel .detail-case:not(.palette-reference)').count(),10);
 assert.equal(await page.locator('#detail-panel .palette-group').count(),5);
 await page.locator('#case-amazonia-palette [data-jump]').nth(2).click();
 await page.waitForFunction(()=>Math.abs(document.querySelector('#detail-video').currentTime-12.933333)<.12);
 await page.locator('#tab-prompts').click();assert.equal(await page.locator('#prompt-variant option').count(),9);
 await page.locator('#detail-close').click();
 await page.goto(base+entry.report);await page.waitForSelector('#shot-list .shot');
 assert.equal(await page.locator('#shot-list .shot').count(),38);
 assert.equal(await page.locator('.camera-cue').count(),45);
 assert.equal(await page.locator('#broll .ref-card').count(),10);
 assert.equal(await page.locator('#palette .ref-card').count(),5);
 assert.equal(await page.locator('#film').getAttribute('src'),'preview-web.mp4');
 assert.equal(await page.locator('#prompt-text').inputValue(),entry.prompts[0].text);
 await page.locator('#film').evaluate(v=>{v.muted=true;return v.play();});
 await page.waitForFunction(()=>document.querySelector('#film').ended,undefined,{timeout:80000});
 assert.match(await page.locator('#media-state').innerText(),/全片播放完毕/);
 assert.equal(await page.locator('#current-id').innerText(),'S38');
 await page.locator('#palette [data-seek]').nth(2).click();
 await page.waitForFunction(()=>Math.abs(document.querySelector('#film').currentTime-13.5)<.1);
 assert.equal(await page.locator('#current-id').innerText(),'S06');
 await page.locator('#play-shot').click();
 await page.waitForFunction(()=>document.querySelector('#media-state').textContent==='本镜播放完毕');
 assert.equal(await page.locator('#current-id').innerText(),'S06');
 assert.ok(Math.abs(await page.locator('#film').evaluate(v=>v.currentTime)-(15.633333-1/30))<.05);
 await page.context().grantPermissions(['clipboard-read','clipboard-write'],{origin:'http://127.0.0.1:8765'});
 for(let i=0;i<entry.prompts.length;i++){
  await page.locator('#prompt-tab-'+i).click();
  assert.equal(await page.locator('#prompt-text').inputValue(),entry.prompts[i].text);
 }
 await page.locator('#copy-prompt').click();await page.waitForFunction(()=>document.querySelector('#copy-prompt').dataset.copyState==='success');
 assert.equal(await page.evaluate(()=>navigator.clipboard.readText()),entry.prompts.at(-1).text);
 await page.locator('#prompt-tab-0').click();
 const metrics=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth-innerWidth,overlap:[...document.querySelectorAll('.camera-cue')].some(c=>{const t=c.querySelector('.cue-time'),h=c.querySelector('h4');return t&&h&&t.getBoundingClientRect().bottom>h.getBoundingClientRect().top+.5})}));
 assert.ok(metrics.overflow<=1,JSON.stringify(metrics));assert.equal(metrics.overlap,false);
 console.log('PASS: Amazonia category, 10 B-roll cases, 5 palettes, full playback, source seeks, single-shot stop, 9 exact prompts, clipboard and desktop layout');
};
